pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title Bus
 * @author Expert Solidity Engineer
 * @notice A smart contract to manage a simple bus service.
 * @dev This contract allows an owner to manage bus trips, set ticket prices,
 * and collect revenue. Passengers can buy tickets for the active trip.
 * It is compliant with OpenZeppelin v4.9.x and Solidity ^0.8.19.
 */
contract Bus is Ownable, ReentrancyGuard {
    //-////////////////////////////////////////////////////////
    //-                      STATE                           -//
    //-////////////////////////////////////////////////////////

    // Trip configuration
    uint256 public ticketPrice;
    uint256 public capacity;
    string public route;

    // Trip state
    uint256 public currentTripId;
    bool public tripIsActive;

    // Passenger tracking per trip
    mapping(uint256 => mapping(address => bool)) public passengersOnTrip;
    mapping(uint256 => uint256) public passengerCountForTrip;

    //-////////////////////////////////////////////////////////
    //-                      EVENTS                          -//
    //-////////////////////////////////////////////////////////

    /**
     * @notice Emitted when the owner updates the settings for future trips.
     * @param newTicketPrice The new price for a single ticket.
     * @param newCapacity The new maximum passenger capacity.
     * @param newRoute The new description of the bus route.
     */
    event SettingsUpdated(uint256 newTicketPrice, uint256 newCapacity, string newRoute);

    /**
     * @notice Emitted when a new trip is started.
     * @param tripId The unique identifier for the new trip.
     * @param route The route for this trip.
     * @param ticketPrice The ticket price for this trip.
     * @param capacity The passenger capacity for this trip.
     */
    event TripStarted(uint256 indexed tripId, string route, uint256 ticketPrice, uint256 capacity);

    /**
     * @notice Emitted when the current trip ends.
     * @param tripId The unique identifier of the concluded trip.
     * @param totalPassengers The number of passengers who bought tickets for this trip.
     * @param revenue The total revenue collected for this trip.
     */
    event TripEnded(uint256 indexed tripId, uint256 totalPassengers, uint256 revenue);

    /**
     * @notice Emitted when a passenger successfully purchases a ticket.
     * @param tripId The ID of the trip the ticket was purchased for.
     * @param passenger The address of the passenger.
     */
    event TicketPurchased(uint256 indexed tripId, address indexed passenger);


    //-////////////////////////////////////////////////////////
    //-                      ERRORS                          -//
    //-////////////////////////////////////////////////////////

    /// @notice The action cannot be performed because a trip is already in progress.
    error Bus__TripAlreadyActive();
    /// @notice The action cannot be performed because no trip is currently active.
    error Bus__TripNotActive();
    /// @notice The bus has reached its maximum passenger capacity for this trip.
    error Bus__BusIsFull();
    /// @notice The sender has already purchased a ticket for the current trip.
    error Bus__AlreadyAPassenger();
    /// @notice The payment sent does not match the required ticket price.
    error Bus__IncorrectPayment();
    /// @notice The settings provided (e.g., price or capacity) are invalid.
    error Bus__InvalidSettings();
    /// @notice There are no funds in the contract to withdraw.
    error Bus__NoRevenueToWithdraw();


    //-////////////////////////////////////////////////////////
    //-                    CONSTRUCTOR                       -//
    //-////////////////////////////////////////////////////////

    /**
     * @notice Initializes the contract.
     * @dev The constructor is empty as per requirements. Use `setTripSettings`
     * to configure the bus service after deployment.
     */
    constructor() {}


    //-////////////////////////////////////////////////////////
    //-                 OWNER FUNCTIONS                      -//
    //-////////////////////////////////////////////////////////

    /**
     * @notice Sets the configuration for future trips.
     * @dev Can only be called by the owner when no trip is active.
     * @param _ticketPrice The price of a single ticket. Must be greater than 0.
     * @param _capacity The maximum number of passengers. Must be greater than 0.
     * @param _route A description of the bus route.
     */
    function setTripSettings(uint256 _ticketPrice, uint256 _capacity, string memory _route) external onlyOwner {
        if (tripIsActive) {
            revert Bus__TripAlreadyActive();
        }
        if (_ticketPrice == 0 || _capacity == 0) {
            revert Bus__InvalidSettings();
        }

        ticketPrice = _ticketPrice;
        capacity = _capacity;
        route = _route;

        emit SettingsUpdated(_ticketPrice, _capacity, _route);
    }

    /**
     * @notice Starts a new trip, allowing passengers to buy tickets.
     * @dev Can only be called by the owner when no trip is active and settings are valid.
     */
    function startTrip() external onlyOwner {
        if (tripIsActive) {
            revert Bus__TripAlreadyActive();
        }
        if (ticketPrice == 0 || capacity == 0) {
            revert Bus__InvalidSettings();
        }

        currentTripId++;
        tripIsActive = true;

        emit TripStarted(currentTripId, route, ticketPrice, capacity);
    }

    /**
     * @notice Ends the current trip, preventing further ticket sales.
     * @dev Can only be called by the owner when a trip is active.
     */
    function endTrip() external onlyOwner {
        if (!tripIsActive) {
            revert Bus__TripNotActive();
        }

        tripIsActive = false;
        uint256 finalPassengerCount = passengerCountForTrip[currentTripId];
        uint256 totalRevenue = finalPassengerCount * ticketPrice;

        emit TripEnded(currentTripId, finalPassengerCount, totalRevenue);
    }

    /**
     * @notice Withdraws the entire contract balance to the owner's address.
     * @dev Can only be called by the owner. Uses ReentrancyGuard.
     */
    function withdraw() external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        if (balance == 0) {
            revert Bus__NoRevenueToWithdraw();
        }

        (bool success, ) = owner().call{value: balance}("");
        require(success, "Bus: Failed to withdraw funds");
    }


    //-////////////////////////////////////////////////////////
    //-                 PUBLIC FUNCTIONS                     -//
    //-////////////////////////////////////////////////////////

    /**
     * @notice Allows a user to purchase a ticket for the current active trip.
     * @dev The user must send the exact `ticketPrice` in ETH.
     */
    function buyTicket() external payable {
        if (!tripIsActive) {
            revert Bus__TripNotActive();
        }
        if (msg.value != ticketPrice) {
            revert Bus__IncorrectPayment();
        }
        if (passengerCountForTrip[currentTripId] >= capacity) {
            revert Bus__BusIsFull();
        }
        if (passengersOnTrip[currentTripId][msg.sender]) {
            revert Bus__AlreadyAPassenger();
        }

        passengersOnTrip[currentTripId][msg.sender] = true;
        passengerCountForTrip[currentTripId]++;

        emit TicketPurchased(currentTripId, msg.sender);
    }


    //-////////////////////////////////////////////////////////
    //-                  VIEW FUNCTIONS                      -//
    //-////////////////////////////////////////////////////////

    /**
     * @notice Checks if a specific address is a passenger on a given trip.
     * @param _tripId The ID of the trip to check.
     * @param _passenger The address to check.
     * @return A boolean indicating if the address is a passenger.
     */
    function isPassenger(uint256 _tripId, address _passenger) external view returns (bool) {
        return passengersOnTrip[_tripId][_passenger];
    }
}

